{"type":"tool_use","timestamp":1789866598713,"sessionID":"ses_f43a32b49ffekDyf3f7QJOk8E5","part":{"type":"tool","tool":"write","callID":"hy2uCy2FCx07gPC1","state":{"status":"completed","input":{"content":"from google.cloud import translate_v3

def translate_text(text: str, target_language_code: str, project_id: str) -> str:
    """Translates text into the target language.

    Args:
        text: The text to translate.
        target_language_code: The language code to translate the text to (e.g., "es" for Spanish).
        project_id: The Google Cloud project ID.

    Returns:
        The translated text.
    """
    client = translate_v3.TranslationServiceClient()
    parent = f"projects/{project_id}/locations/global"

    response = client.translate_text(
        request={
            "parent": parent,
            "contents": [text],
            "target_language_code": target_language_code,
        }
    )

    translated_text = ""
    for translation in response.translations:
        translated_text += translation.translated_text
    return translated_text
